-- ========================================================
-- UNIVERSE HUB POS: SUPABASE PRODUCTS REPAIR & RESTORE
-- Run this in Supabase Dashboard -> SQL Editor                 
-- ========================================================

-- 1. Ensure table has correct structure
CREATE TABLE IF NOT EXISTS public.products (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category VARCHAR(255) NOT NULL,
    product_type VARCHAR(255) DEFAULT 'general',
    phone_brand VARCHAR(255),
    phone_model VARCHAR(255),
    phone_color VARCHAR(255),
    phone_imei VARCHAR(255),
    phone_storage VARCHAR(255),
    serial_number VARCHAR(255),
    sku VARCHAR(255) NOT NULL,
    barcode VARCHAR(255),
    quantity INTEGER DEFAULT 0,
    min_stock_level INTEGER DEFAULT 10,
    cost_price NUMERIC(10, 2) NOT NULL DEFAULT 0,
    selling_price NUMERIC(10, 2) NOT NULL DEFAULT 0,
    supplier VARCHAR(255),
    warranty_period_months INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Enable RLS & Allow full access
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow full access to products" ON public.products;
CREATE POLICY "Allow full access to products" ON public.products FOR ALL USING (true) WITH CHECK (true);

-- 2. Clear old shifted/corrupted products and re-insert clean data
TRUNCATE TABLE public.products RESTART IDENTITY CASCADE;

